public partial class OrbitVR {
 static readonly Stopwatch Clock=Stopwatch.StartNew();
 static double lastTelemetry=-10, sampleTime; static uint samplePid;
 static Compositor_CumulativeStats previous; static bool sampleReady;
 static Color hudBg=Color.FromArgb(16,20,27),hudText=Color.FromArgb(238,244,252),hudAccent=Color.FromArgb(140,197,255);
 static ulong hudHandle; static bool hudEnabled; static string hudAnchor="wrist-left";
 // Monotonic elapsed time and game submissions, not overlay painting or refresh Hz.
 static Dictionary<string,object> Measure(Compositor_CumulativeStats now,uint pid,double seconds,float hz){
  var r=new Dictionary<string,object>{{"appFps",null},{"cpuMs",null},{"gpuMs",null},{"reprojection",null},{"dropped",null},{"refreshHz",hz>0?(object)hz:null},{"scenePid",pid},{"status","Waiting for game frames"}};
  if(pid==0||now.m_nPid!=pid||double.IsNaN(now.m_flSumApplicationCPUTimeMS)||double.IsNaN(now.m_flSumApplicationGPUTimeMS)||double.IsInfinity(now.m_flSumApplicationCPUTimeMS)||double.IsInfinity(now.m_flSumApplicationGPUTimeMS)||(now.m_nNumFrameSubmits==0&&now.m_nNumFramePresents>0)){sampleReady=false;return r;}
  if(!sampleReady||samplePid!=pid||now.m_nNumFrameSubmits<previous.m_nNumFrameSubmits||now.m_nNumFramePresents<previous.m_nNumFramePresents||now.m_nNumReprojectedFrames<previous.m_nNumReprojectedFrames||now.m_nNumDroppedFrames<previous.m_nNumDroppedFrames||now.m_flSumApplicationCPUTimeMS<previous.m_flSumApplicationCPUTimeMS||now.m_flSumApplicationGPUTimeMS<previous.m_flSumApplicationGPUTimeMS){previous=now;sampleTime=seconds;samplePid=pid;sampleReady=true;return r;}
  double elapsed=seconds-sampleTime;if(elapsed<1)return r;
  uint submits=now.m_nNumFrameSubmits-previous.m_nNumFrameSubmits,presents=now.m_nNumFramePresents-previous.m_nNumFramePresents;
  r["appFps"]=Math.Round(submits/elapsed,1);r["reprojection"]=presents>0?(object)Math.Round(Math.Min(100,100.0*(now.m_nNumReprojectedFrames-previous.m_nNumReprojectedFrames)/presents),1):null;r["dropped"]=now.m_nNumDroppedFrames-previous.m_nNumDroppedFrames;
  if(submits>0){r["cpuMs"]=Math.Round((now.m_flSumApplicationCPUTimeMS-previous.m_flSumApplicationCPUTimeMS)/submits,2);r["gpuMs"]=Math.Round((now.m_flSumApplicationGPUTimeMS-previous.m_flSumApplicationGPUTimeMS)/submits,2);}r["status"]="SteamVR compositor · last "+Math.Round(elapsed,1)+" s";previous=now;sampleTime=seconds;return r;
 }
 static void TelemetryTests(){sampleReady=false;var s=new Compositor_CumulativeStats{m_nPid=42};Measure(s,42,0,90);s.m_nNumFrameSubmits=45;s.m_nNumFramePresents=90;s.m_nNumReprojectedFrames=45;s.m_flSumApplicationCPUTimeMS=225;s.m_flSumApplicationGPUTimeMS=450;var r=Measure(s,42,1,90);if(Convert.ToDouble(r["appFps"])!=45||Convert.ToDouble(r["reprojection"])!=50||Convert.ToDouble(r["gpuMs"])!=10)throw new Exception("Compositor measurement failed.");if(Measure(s,43,2,90)["appFps"]!=null)throw new Exception("Stale process statistics accepted.");sampleReady=false;}
 static string Property(uint id,ETrackedDeviceProperty prop){var error=ETrackedPropertyError.TrackedProp_Success;var text=new StringBuilder(256);system.GetStringTrackedDeviceProperty(id,prop,text,256,ref error);return error==ETrackedPropertyError.TrackedProp_Success?text.ToString():"Unknown";}
 static object Devices(){var list=new List<object>();var poses=new TrackedDevicePose_t[OpenVR.k_unMaxTrackedDeviceCount];system.GetDeviceToAbsoluteTrackingPose(ETrackingUniverseOrigin.TrackingUniverseStanding,0,poses);for(uint i=0;i<OpenVR.k_unMaxTrackedDeviceCount;i++){if(!system.IsTrackedDeviceConnected(i))continue;var error=ETrackedPropertyError.TrackedProp_Success;float battery=system.GetFloatTrackedDeviceProperty(i,ETrackedDeviceProperty.Prop_DeviceBatteryPercentage_Float,ref error);object value=error==ETrackedPropertyError.TrackedProp_Success&&battery>=0&&battery<=1?(object)Math.Round(battery*100):null;error=ETrackedPropertyError.TrackedProp_Success;bool charging=system.GetBoolTrackedDeviceProperty(i,ETrackedDeviceProperty.Prop_DeviceIsCharging_Bool,ref error);list.Add(new{id=i,kind=system.GetTrackedDeviceClass(i).ToString().Replace("TrackedDeviceClass_",""),role=system.GetControllerRoleForTrackedDeviceIndex(i).ToString(),model=Property(i,ETrackedDeviceProperty.Prop_ModelNumber_String),battery=value,charging=error==ETrackedPropertyError.TrackedProp_Success&&charging,tracking=poses[i].bPoseIsValid});}return list;}
 static void TickTools(){double now=Clock.Elapsed.TotalSeconds;if(now-lastTelemetry<1)return;lastTelemetry=now;foreach(var p in extraPanels)Emit(new{type="panel-visibility",panelId=p.Key,visible=fixture?fixtureVisible:OpenVR.Overlay.IsOverlayVisible(p.Value.handle)});Dictionary<string,object> stats;object devices;float x=0,z=0;bool room=false;if(fixture){stats=new Dictionary<string,object>{{"appFps",45.0},{"cpuMs",5.0},{"gpuMs",10.0},{"refreshHz",90.0},{"reprojection",50.0},{"dropped",0},{"status","Fixture · synthetic compositor counters"}};devices=new[]{new{id=0,kind="HMD",role="Invalid",model="Fixture headset",battery=(object)null,charging=false,tracking=true},new{id=1,kind="Controller",role="LeftHand",model="Fixture controller",battery=(object)75,charging=false,tracking=true}};x=2;z=3;room=true;}else{var c=new Compositor_CumulativeStats();OpenVR.Compositor.GetCumulativeStats(ref c,(uint)Marshal.SizeOf(typeof(Compositor_CumulativeStats)));var error=ETrackedPropertyError.TrackedProp_Success;float hz=system.GetFloatTrackedDeviceProperty(0,ETrackedDeviceProperty.Prop_DisplayFrequency_Float,ref error);stats=Measure(c,OpenVR.Compositor.GetCurrentSceneFocusProcess(),now,error==ETrackedPropertyError.TrackedProp_Success?hz:0);devices=Devices();room=OpenVR.Chaperone.GetPlayAreaSize(ref x,ref z);if(hudEnabled)DrawHud(stats);}Emit(new{type="telemetry",stats=stats,devices=devices,room=new{available=room,width=x,depth=z},fixture=fixture});}
 static string Metric(Dictionary<string,object> s,string key,string suffix){return s[key]==null?"—":Convert.ToString(s[key])+suffix;}
 static void DrawHud(Dictionary<string,object> s){if(hudHandle==0)return;using(var bmp=new Bitmap(640,160,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(bmp)){g.Clear(Color.FromArgb(238,hudBg));using(var font=new Font("Segoe UI",25,FontStyle.Bold))using(var detail=new Font("Segoe UI",16))using(var ink=new SolidBrush(hudText))using(var accent=new SolidBrush(hudAccent)){g.DrawString(Metric(s,"appFps"," FPS")+"   "+Metric(s,"refreshHz"," Hz"),font,accent,18,14);g.DrawString("CPU "+Metric(s,"cpuMs"," ms")+"   GPU "+Metric(s,"gpuMs"," ms"),detail,ink,18,64);g.DrawString("Reprojected "+Metric(s,"reprojection","%")+"   Dropped "+Metric(s,"dropped",""),detail,ink,18,106);}}var bits=bmp.LockBits(new Rectangle(0,0,640,160),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{byte[] b=new byte[640*160*4];Marshal.Copy(bits.Scan0,b,0,b.Length);SubmitTexture(hudHandle,b,640,160,false);}finally{bmp.UnlockBits(bits);}}}
}
